using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace CSharpGameEngine.CodeAnalysis;

internal static class GameSystemSnapshotEmitter {
    private const string HintName="GameSystem.Snapshot.g.cs";
    internal static void Emit(SourceProductionContext Context,GameSystemRegistry Registry){
        List<string>Lines=[
            "// <auto-generated/>",
            "#nullable enable",
            "namespace CSharpGameEngine.Entities;",
            "public partial struct World {",
        ];
        foreach(var Archetype in Registry.Archetypes){
            string Descriptors=string.Join(", ",SortedComponents(Archetype,Registry).Select(static Component=>$"global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.Descriptor"));
            Lines.Add($"    private static readonly global::CSharpGameEngine.Entities.EcsSnapshotArchetypeDescriptor Snapshot{Archetype.Name} = global::CSharpGameEngine.Entities.EcsSnapshotArchetypeDescriptor.Create({Descriptors});");
        }
        string Archetypes=string.Join(", ",Registry.Archetypes.Select(static Archetype=>$"Snapshot{Archetype.Name}"));
        Lines.Add($"    public static string SnapshotSchemaFingerprint {{ get; }} = global::CSharpGameEngine.Entities.EcsSnapshotSchema.ComputeFingerprint({Archetypes});");
        Lines.AddRange(BuildCapture(Registry));
        Lines.AddRange(BuildRestore(Registry));
        Lines.AddRange(BuildValidate(Registry));
        Lines.AddRange(BuildApply(Registry));
        Lines.Add("}");
        Context.AddSource(HintName,SourceText.From(string.Join(((char)10).ToString(),Lines),Encoding.UTF8));
    }

    private static List<string>BuildCapture(GameSystemRegistry Registry){
        if(Registry.Archetypes.IsEmpty){
            return[
                "    public byte[] CaptureSnapshot(ulong Tick, string EventHash) {",
                "        this.CaptureSnapshotState(out var Cells, out var Entities);",
                "        return global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.Write(SnapshotSchemaFingerprint, Tick, EventHash, Cells, Entities);",
                "    }",
                "    public byte[] UpdateSnapshot(global::System.ReadOnlySpan<byte> PreviousArtifact, ulong Tick, string EventHash) {",
                "        if (!global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.TryRead(PreviousArtifact, SnapshotSchemaFingerprint, out var Previous, out var Error)) throw new global::System.IO.InvalidDataException(Error.Message);",
                "        this.CaptureSnapshotState(out var Cells, out var Entities);",
                "        return global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.Merge(Previous!, SnapshotSchemaFingerprint, Tick, EventHash, Cells, Entities);",
                "    }",
                "    private void CaptureSnapshotState(out global::CSharpGameEngine.Contracts.WorldCellId[] Cells, out global::CSharpGameEngine.Entities.EcsSnapshotEntityData[] Entities) {",
                """        if (this.Commands.Count != 0 || this.Commands.IsSystemExecuting) throw new global::System.InvalidOperationException("Snapshot capture requires a completed structural barrier.");""",
                "        Cells = this.CellEntities.Keys.OrderBy(static Cell => Cell).ToArray();",
                "        Entities = global::System.Array.Empty<global::CSharpGameEngine.Entities.EcsSnapshotEntityData>();",
                "    }",
            ];
        }
        List<string>Lines=[
            "    public byte[] CaptureSnapshot(ulong Tick, string EventHash) {",
            "        this.CaptureSnapshotState(out var Cells, out var Entities);",
            "        return global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.Write(SnapshotSchemaFingerprint, Tick, EventHash, Cells, Entities);",
            "    }",
            "    public byte[] UpdateSnapshot(global::System.ReadOnlySpan<byte> PreviousArtifact, ulong Tick, string EventHash) {",
            "        if (!global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.TryRead(PreviousArtifact, SnapshotSchemaFingerprint, out var Previous, out var Error)) throw new global::System.IO.InvalidDataException(Error.Message);",
            "        this.CaptureSnapshotState(out var Cells, out var Entities);",
            "        return global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.Merge(Previous!, SnapshotSchemaFingerprint, Tick, EventHash, Cells, Entities);",
            "    }",
            "    private void CaptureSnapshotState(out global::CSharpGameEngine.Contracts.WorldCellId[] Cells, out global::CSharpGameEngine.Entities.EcsSnapshotEntityData[] Entities) {",
            "        if (this.Commands.Count != 0 || this.Commands.IsSystemExecuting) throw new global::System.InvalidOperationException(\"Snapshot capture requires a completed structural barrier.\");",
            "        Cells = this.CellEntities.Keys.OrderBy(static Cell => Cell).ToArray();",
            "        var Result = new global::System.Collections.Generic.List<global::CSharpGameEngine.Entities.EcsSnapshotEntityData>();",
            "        for (int Slot = 0; Slot < this.EntityArchetypeIndices.Count; Slot++) {",
            "            ref var Location = ref this.EntityArchetypeIndices.GetRefUnchecked(Slot);",
            "            if (!Location.Cell.IsValid || !Location.Persistent.IsValid || !this.IsAlive(Location.Entity)) continue;",
            "            var Components = new global::System.Collections.Generic.List<global::CSharpGameEngine.Entities.EcsSnapshotComponentData>();",
            "            string ArchetypeKey;",
            "            bool EntityEnabled;",
            "            switch (Location.Archetype) {",
        ];
        foreach(var Archetype in Registry.Archetypes){
            Lines.Add($"                case Archetype.{Archetype.Name}:");
            Lines.Add($"                    ArchetypeKey = Snapshot{Archetype.Name}.Key;");
            Lines.Add($"                    EntityEnabled = this.{Archetype.Name}.IsEntityEnabledUnchecked(Location.Index);");
            foreach(var Component in SortedComponents(Archetype,Registry)){
                Lines.Add($"                    if (!global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.IsTransient) {{");
                Lines.Add($"                        ref var SnapshotValue{Component.Index} = ref this.{Archetype.Name}.Get{Component.FieldName}RefUnchecked(Location.Index);");
                Lines.Add($"                        Components.Add(new(global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.Descriptor.TypeId, this.{Archetype.Name}.Is{Component.FieldName}EnabledUnchecked(Location.Index), global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.Serialize(in SnapshotValue{Component.Index})));");
                Lines.Add("                    }");
            }
            Lines.Add("                    break;");
        }
        Lines.Add("                default: throw new global::System.InvalidOperationException(\"A live entity has no generated snapshot archetype.\");");
        Lines.Add("            }");
        Lines.Add("            Result.Add(new(Location.Cell, Location.Persistent, ArchetypeKey, EntityEnabled, Components));");
        Lines.Add("        }");
        Lines.Add("        Entities = Result.ToArray();");
        Lines.Add("    }");
        return Lines;
    }

    private static List<string>BuildRestore(GameSystemRegistry Registry)=>[
        "    public global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult RestoreSnapshot(global::System.ReadOnlySpan<byte> Artifact) {",
        "        if (this.Commands.Count != 0 || this.Commands.IsSystemExecuting) return global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult.Reject(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.WorldBusy, \"Snapshot restore requires a completed structural barrier.\");",
        "        if (!global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.TryRead(Artifact, SnapshotSchemaFingerprint, out var Document, out var Error)) return global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult.Reject(Error.Code, Error.Message);",
        "        return this.ApplySnapshotDocument(Document!);",
        "    }",
        "    public global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult ApplyPendingSnapshot(global::CSharpGameEngine.Entities.EcsSnapshotPending Pending) {",
        "        global::System.ArgumentNullException.ThrowIfNull(Pending);",
        "        if (!global::System.String.Equals(Pending.Document.SchemaFingerprint, SnapshotSchemaFingerprint, global::System.StringComparison.Ordinal)) return global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult.Reject(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.SchemaMismatch, \"Pending snapshot belongs to another generated schema.\");",
        "        if (this.Commands.Count != 0 || this.Commands.IsSystemExecuting) return global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult.Reject(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.WorldBusy, \"Pending snapshot restore requires a completed structural barrier.\");",
        "        return this.ApplySnapshotDocument(Pending.Document);",
        "    }",
        "    private global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult ApplySnapshotDocument(global::CSharpGameEngine.Entities.EcsSnapshotDocument Document) {",
        "        var LoadedCells = new global::System.Collections.Generic.HashSet<global::CSharpGameEngine.Contracts.WorldCellId>();",
        "        foreach (var Cell in Document.CapturedCells) { if (this.HasOwnedCell(Cell)) LoadedCells.Add(Cell); }",
        "        var Saved = Document.Entities.Where(Entity => LoadedCells.Contains(Entity.Cell)).ToDictionary(static Entity => Entity.Persistent);",
        "        foreach (var Entry in Saved.Values) {",
        "            if (!this.TryResolve(Entry.Persistent, out var Entity)) return global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult.Reject(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.EntityMissing, $\"Loaded cell {Entry.Cell} is missing persistent entity {Entry.Persistent}; reload its base cell before applying the delta.\");",
        "            if (this.GetOwningCell(Entity) != Entry.Cell) return global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult.Reject(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.CellMismatch, $\"Persistent entity {Entry.Persistent} belongs to another cell.\");",
        "            if (!this.ValidateSnapshotEntry(Entity, Entry, out var ValidationError)) return global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult.Reject(ValidationError.Code, ValidationError.Message);",
        "        }",
        "        var Remove = new global::System.Collections.Generic.List<Entity>();",
        "        for (int Slot = 0; Slot < this.EntityArchetypeIndices.Count; Slot++) {",
        "            ref var Location = ref this.EntityArchetypeIndices.GetRefUnchecked(Slot);",
        "            if (!this.IsAlive(Location.Entity) || !LoadedCells.Contains(Location.Cell) || !Location.Persistent.IsValid) continue;",
        "            if (!Saved.ContainsKey(Location.Persistent)) Remove.Add(Location.Entity);",
        "        }",
        "        foreach (var Entry in Saved.Values) { this.ApplySnapshotEntry(this.PersistentEntities[Entry.Persistent], Entry); }",
        "        foreach (var Entity in Remove) { this.Destroy(Entity); }",
        "        var PendingCells = Document.CapturedCells.Where(Cell => !LoadedCells.Contains(Cell)).ToHashSet();",
        "        global::CSharpGameEngine.Entities.EcsSnapshotPending? Pending = PendingCells.Count == 0 ? null : new(global::CSharpGameEngine.Entities.EcsSnapshotArtifactCodec.Filter(Document, PendingCells));",
        "        return new global::CSharpGameEngine.Entities.EcsSnapshotRestoreResult(true, Saved.Count, Remove.Count, Pending, global::CSharpGameEngine.Entities.EcsSnapshotError.None);",
        "    }",
    ];

    private static List<string>BuildValidate(GameSystemRegistry Registry){
        List<string>Lines=[
            "    private bool ValidateSnapshotEntry(Entity Entity, global::CSharpGameEngine.Entities.EcsSnapshotEntityData Entry, out global::CSharpGameEngine.Entities.EcsSnapshotError Error) {",
            "        ref var Location = ref this.EntityArchetypeIndices.GetRefUnchecked(Entity.Id);",
            "        switch (Location.Archetype) {",
        ];
        foreach(var Archetype in Registry.Archetypes){
            Lines.Add($"            case Archetype.{Archetype.Name}: {{");
            Lines.Add($"                if (!global::System.String.Equals(Entry.ArchetypeKey, Snapshot{Archetype.Name}.Key, global::System.StringComparison.Ordinal)) {{ Error = new(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.ArchetypeMismatch, $\"Snapshot archetype does not match persistent entity {{Entry.Persistent}}.\"); return false; }}");
            Lines.Add("                int ComponentIndex = 0;");
            foreach(var Component in SortedComponents(Archetype,Registry)){
                Lines.Add($"                if (!global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.IsTransient) {{");
                Lines.Add($"                    if ((uint)ComponentIndex >= (uint)Entry.Components.Count || !global::System.String.Equals(Entry.Components[ComponentIndex].TypeId, global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.Descriptor.TypeId, global::System.StringComparison.Ordinal)) {{ Error = new(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.ComponentMismatch, $\"Snapshot component order does not match persistent entity {{Entry.Persistent}}.\"); return false; }}");
                Lines.Add($"                    if (!global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.TryDeserialize(Entry.Components[ComponentIndex].Payload, out _, out var ComponentError)) {{ Error = new(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.ComponentMismatch, ComponentError); return false; }}");
                Lines.Add("                    ComponentIndex++;");
                Lines.Add("                }");
            }
            Lines.Add("                if (ComponentIndex != Entry.Components.Count) { Error = new(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.ComponentMismatch, $\"Snapshot has unexpected components for persistent entity {Entry.Persistent}.\"); return false; }");
            Lines.Add("                Error = global::CSharpGameEngine.Entities.EcsSnapshotError.None; return true;");
            Lines.Add("            }");
        }
        Lines.Add("            default: Error = new(global::CSharpGameEngine.Entities.EcsSnapshotErrorCode.ArchetypeMismatch, \"Snapshot entity has no generated archetype.\"); return false;");
        Lines.Add("        }");
        Lines.Add("    }");
        return Lines;
    }

    private static List<string>BuildApply(GameSystemRegistry Registry){
        if(Registry.Archetypes.IsEmpty){
            return[
                "    private void ApplySnapshotEntry(Entity Entity, global::CSharpGameEngine.Entities.EcsSnapshotEntityData Entry) {",
                """        throw new global::System.InvalidOperationException("A schema without archetypes cannot apply an entity snapshot.");""",
                "    }",
            ];
        }
        List<string>Lines=[
            "    private void ApplySnapshotEntry(Entity Entity, global::CSharpGameEngine.Entities.EcsSnapshotEntityData Entry) {",
            "        ref var Location = ref this.EntityArchetypeIndices.GetRefUnchecked(Entity.Id);",
            "        var Version = this.AdvanceChangeVersion();",
            "        int ComponentIndex = 0;",
            "        switch (Location.Archetype) {",
        ];
        foreach(var Archetype in Registry.Archetypes){
            Lines.Add($"            case Archetype.{Archetype.Name}:");
            foreach(var Component in SortedComponents(Archetype,Registry)){
                Lines.Add($"                if (!global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.IsTransient) {{");
                Lines.Add($"                    global::CSharpGameEngine.Entities.EcsSnapshotComponentCodec<{Component.TypeFullyQualifiedName}>.TryDeserialize(Entry.Components[ComponentIndex].Payload, out var SnapshotValue{Component.Index}, out _);");
                Lines.Add($"                    this.{Archetype.Name}.Get{Component.FieldName}RefUnchecked(Location.Index) = SnapshotValue{Component.Index};");
                Lines.Add($"                    this.{Archetype.Name}.Set{Component.FieldName}EnabledUnchecked(Location.Index, Entry.Components[ComponentIndex].Enabled, Version);");
                Lines.Add("                    ComponentIndex++;");
                Lines.Add("                }");
            }
            Lines.Add($"                this.{Archetype.Name}.SetEntityEnabledUnchecked(Location.Index, Entry.Enabled);");
            Lines.Add("                return;");
        }
        Lines.Add("            default: throw new global::System.InvalidOperationException(\"Validated snapshot entity lost its archetype.\");");
        Lines.Add("        }");
        Lines.Add("    }");
        return Lines;
    }

    private static IEnumerable<GameSystemComponentInfo>SortedComponents(GameSystemArchetypeInfo Archetype,GameSystemRegistry Registry)=>
        Archetype.ComponentIndices.Select(Index=>Registry.ComponentsByIndex[Index]).OrderBy(static Component=>Component.TypeFullyQualifiedName,StringComparer.Ordinal);
}
